const META_PHONE_NUMBER_ID = 'YOUR_WHATSAPP_PHONE_NUMBER_ID';
const META_ACCESS_TOKEN = 'YOUR_META_PERMANENT_ACCESS_TOKEN';
const OFFICIAL_TEMPLATE_NAME = 'dental_appointment_reminder';

// للتجربة الفورية على أي موعد غداً اجعل TEST_ANY_TOMORROW = true، وللإنتاج اتركها false (من 22 إلى 26 ساعة)
const TEST_ANY_TOMORROW = false;

function parseCairoDateTime(dateStr, timeStr) {
  const [year, month, day] = String(dateStr).split('-').map(Number);
  const cleanTime = String(timeStr || '05:00 PM').trim().toUpperCase();
  const match = cleanTime.match(/(\d{1,2}):(\d{2})\s*(AM|PM)?/);
  let hours = match ? parseInt(match[1], 10) : 17;
  const minutes = match ? parseInt(match[2], 10) : 0;
  const period = match ? match[3] : null;
  if (period === 'PM' && hours < 12) hours += 12;
  if (period === 'AM' && hours === 12) hours = 0;
  const isoStr = `${String(year).padStart(4,'0')}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}T${String(hours).padStart(2,'0')}:${String(minutes).padStart(2,'0')}:00+02:00`;
  return new Date(isoStr);
}

const now = new Date();
const results = [];

for (const wrapped of $input.all()) {
  const item = wrapped.json;
  if (!item || !item.id) continue;

  const apptTime = parseCairoDateTime(item.appointment_date, item.appointment_time);
  const diffInHours = (apptTime - now) / (1000 * 60 * 60);

  // مستحيل يبعت لميعاد فات (diffInHours <= 0)
  if (diffInHours <= 0) continue;
  if (!TEST_ANY_TOMORROW && (diffInHours < 22 || diffInHours > 26)) continue;

  let phone = String(item.phone || '').trim().replace(/^\+/, '');
  if (phone.startsWith('01')) phone = '20' + phone.slice(1);

  const patientName = item.patient_name || 'عميلنا العزيز';
  const appointmentDate = item.appointment_date;
  const doctorName = item.doctor_name || 'الطبيب المختص';
  const appointmentTime = item.appointment_time || '05:00 PM';

  // الـ 4 متغيرات بنفس ترتيب قالب dental_appointment_reminder في ميتا بالظبط:
  // {{1}}: اسم المريض | {{2}}: التاريخ | {{3}}: اسم الدكتور | {{4}}: الساعة
  const templatePayload = {
    messaging_product: 'whatsapp',
    to: phone,
    type: 'template',
    template: {
      name: OFFICIAL_TEMPLATE_NAME,
      language: { code: 'ar' },
      components: [
        {
          type: 'body',
          parameters: [
            { type: 'text', text: patientName },
            { type: 'text', text: appointmentDate },
            { type: 'text', text: doctorName },
            { type: 'text', text: appointmentTime }
          ]
        },
        {
          type: 'button',
          sub_type: 'quick_reply',
          index: '0',
          parameters: [{ type: 'payload', payload: 'CONFIRM_APPT' }]
        },
        {
          type: 'button',
          sub_type: 'quick_reply',
          index: '1',
          parameters: [{ type: 'payload', payload: 'CANCEL_APPT' }]
        }
      ]
    }
  };

  results.push({
    json: {
      appointment_id: item.id,
      phone: phone,
      phone_number_id: META_PHONE_NUMBER_ID,
      meta_access_token: META_ACCESS_TOKEN,
      diff_hours: Number(diffInHours.toFixed(2)),
      meta_payload: templatePayload
    }
  });
}

return results;

